SELECT jsonb_build_object(
 'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'definition',pg_get_functiondef(p.oid),'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service',has_function_privilege('service_role',p.oid,'EXECUTE')) ORDER BY p.oid::regprocedure::text) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname IN ('create_user_from_registration','create_user_in_organization_with_data_ws','get_occasion_for_context_v1','get_news_for_context_v1','get_news_read_state_v1','mark_news_read_client_sync_v1','get_user_group_info_with_users','get_public_client_sync_component_core_v1','can_read_group_data_security_v1','can_read_news_data_security_v1','get_news_with_views')),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.tablename,p.policyname) FROM pg_policies p WHERE schemaname='public' AND tablename IN ('user_group_info','user_groups','user_news','occasions','places','news','email_templates')),
 'acl',(SELECT jsonb_agg(jsonb_build_object('table',t,'role',r,'privilege',v,'allowed',has_table_privilege(r,'public.'||t,v)) ORDER BY t,r,v) FROM unnest(ARRAY['user_group_info','user_groups','user_news','occasions','places','news','email_templates']) t CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) r CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) v),
 'defaults',(SELECT jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(defaclrole),'schema',coalesce(n.nspname,'GLOBAL'),'type',defaclobjtype,'acl',defaclacl::text) ORDER BY pg_get_userbyid(defaclrole),coalesce(n.nspname,'GLOBAL'),defaclobjtype) FROM pg_default_acl a LEFT JOIN pg_namespace n ON n.oid=a.defaclnamespace WHERE n.nspname IN ('public','eshop') OR a.defaclnamespace=0)
);
